SELECT #{end} time,url type,SUM(sum) count
FROM ntc_reject_url_statistic
where stat_time between #{start} and #{end}
group by url
ORDER BY sum desc
LIMIT 10;

SELECT #{end} time,url type,ip_addr ip,sum count
   FROM ntc_reject_url_statistic
   where stat_time  between #{start} and #{end}
   ORDER BY sum desc
   LIMIT 10;

SELECT #{end} time ,website type ,sum(sum) count
FROM ntc_reject_website_statistic
where stat_time between #{start} and #{end}
group by website
ORDER BY sum desc
LIMIT 10;

SELECT #{end} time,website type,ip_addr ip,sum count
    FROM ntc_reject_website_statistic
    where stat_time between #{start} and #{end}
    ORDER BY sum desc
    LIMIT 10;

